class TTLCache:
    def __init__(self, ttl, max_entries, clock):
        self.ttl = ttl
        self.max_entries = max_entries
        self.clock = clock
        self._items = {}

    def set(self, key, value):
        self._items[key] = (value, self.clock())

    def get(self, key):
        item = self._items.get(key)
        if item is None:
            return None
        value, created = item
        if self.clock() - created > self.ttl:
            del self._items[key]
            return None
        return value

