import unittest
from config import merge_config

class ConfigTests(unittest.TestCase):
    def test_recursive_merge_and_list_replace(self):
        base = {'api': {'timeout': 5, 'headers': {'a': '1'}}, 'tags': ['old']}
        override = {'api': {'headers': {'b': '2'}}, 'tags': ['new']}
        merged = merge_config(base, override)
        self.assertEqual(merged, {'api': {'timeout': 5, 'headers': {'a': '1', 'b': '2'}}, 'tags': ['new']})
        self.assertEqual(base, {'api': {'timeout': 5, 'headers': {'a': '1'}}, 'tags': ['old']})
        self.assertEqual(override, {'api': {'headers': {'b': '2'}}, 'tags': ['new']})

    def test_result_does_not_alias_inputs(self):
        base = {'nested': {'values': [1]}}
        override = {'added': {'values': [2]}}
        merged = merge_config(base, override)
        merged['nested']['values'].append(3)
        merged['added']['values'].append(4)
        self.assertEqual(base['nested']['values'], [1])
        self.assertEqual(override['added']['values'], [2])

