import unittest
from archive_paths import safe_member_path

class ArchivePathTests(unittest.TestCase):
    def test_safe_normalization(self):
        self.assertEqual(safe_member_path('models/./qwen/model.gguf'), 'models/qwen/model.gguf')
        self.assertEqual(safe_member_path('a//b.txt'), 'a/b.txt')

    def test_rejects_unsafe_paths(self):
        for value in ('/etc/passwd', '../secret', 'a/../../secret', r'a\..\secret', r'C:\temp\x', '', '.', './'):
            with self.subTest(value=value):
                with self.assertRaises(ValueError):
                    safe_member_path(value)

    def test_rejects_hidden_parent_even_if_normpath_looks_safe(self):
        with self.assertRaises(ValueError):
            safe_member_path('safe/../other.txt')

