import unittest
from datetime import datetime, timezone
from retry import parse_retry_after

class RetryTests(unittest.TestCase):
    def setUp(self):
        self.now = datetime(2026, 8, 13, 12, 0, 0, 500000, tzinfo=timezone.utc)

    def test_seconds(self):
        self.assertEqual(parse_retry_after(' 120 ', self.now), 120)
        self.assertEqual(parse_retry_after('0', self.now), 0)
        self.assertIsNone(parse_retry_after('-1', self.now))
        self.assertIsNone(parse_retry_after('+2', self.now))

    def test_http_date_rounds_up(self):
        self.assertEqual(parse_retry_after('Thu, 13 Aug 2026 12:00:02 GMT', self.now), 2)
        self.assertEqual(parse_retry_after('Thu, 13 Aug 2026 11:59:00 GMT', self.now), 0)

    def test_invalid(self):
        for value in (None, '', 'tomorrow', '1.5'):
            self.assertIsNone(parse_retry_after(value, self.now))

