import unittest
from permissions import is_allowed
from policy import POLICIES

class PermissionTests(unittest.TestCase):
    def test_allow_and_unknown(self):
        self.assertTrue(is_allowed(['editor'], 'write'))
        self.assertFalse(is_allowed(['missing'], 'read'))
        self.assertFalse(is_allowed(['editor'], 'publish'))

    def test_deny_overrides_any_allow(self):
        self.assertFalse(is_allowed(['editor', 'suspended'], 'write'))
        self.assertFalse(is_allowed(['viewer', 'editor'], 'delete'))

    def test_policy_not_mutated(self):
        before = {key: {'allow': set(value['allow']), 'deny': set(value['deny'])} for key, value in POLICIES.items()}
        is_allowed(['viewer', 'editor'], 'read')
        self.assertEqual(POLICIES, before)

