import unittest
from scheduler import build_batches

class SchedulerTests(unittest.TestCase):
    def test_respects_limits_and_order(self):
        tasks = [{'id': 'a', 'weight': 3}, {'id': 'b', 'weight': 4}, {'id': 'c', 'weight': 5}, {'id': 'd', 'weight': 1}]
        batches = build_batches(tasks, 2, 7)
        self.assertEqual([[item['id'] for item in batch] for batch in batches], [['a', 'b'], ['c', 'd']])
        self.assertEqual([item['id'] for item in tasks], ['a', 'b', 'c', 'd'])

    def test_overweight_is_alone_without_empty_batch(self):
        tasks = [{'id': 'a', 'weight': 2}, {'id': 'huge', 'weight': 20}, {'id': 'b', 'weight': 2}]
        self.assertEqual([[item['id'] for item in batch] for batch in build_batches(tasks, 3, 5)], [['a'], ['huge'], ['b']])

    def test_empty_and_invalid_limits(self):
        self.assertEqual(build_batches([], 2, 4), [])
        for limits in ((0, 4), (2, 0), (-1, 3)):
            with self.assertRaises(ValueError):
                build_batches([], *limits)
